import type {
  Product,
  ProductBundle,
  ProductContentSection,
  ProductFilterAttributes,
  ProductSpec,
  ProductSectionConfig,
  ProductSectionId,
  ProductStatus,
} from "@/types/product";

type ProductSeed = {
  id: string;
  section: ProductSectionId;
  name: string;
  brand: string;
  originalPrice?: number;
  salePrice: number;
  stockQuantity: number;
  tags: string[];
  highlights: string[];
  featuredSpecs: ProductSpec[];
  filterAttributes?: ProductFilterAttributes;
  description?: string;
  promotion?: string;
  status?: ProductStatus;
  warranty?: string;
  bundles?: ProductBundle[];
  contentSections?: ProductContentSection[];
};

const placeholderImage = "/product-placeholder.svg";

function createProduct(seed: ProductSeed): Product {
  const discount = seed.originalPrice
    ? Math.round(((seed.originalPrice - seed.salePrice) / seed.originalPrice) * 100)
    : undefined;
  const featuredSpecs = seed.featuredSpecs;
  const description =
    seed.description ??
    `${seed.name} là sản phẩm chính hãng, phù hợp cho nhu cầu học tập, làm việc và giải trí.`;
  const contentSections =
    seed.contentSections ??
    [
      {
        id: "overview",
        title: "Tổng quan sản phẩm",
        paragraphs: [description, seed.highlights.join(" • ")],
        images: [placeholderImage],
      },
      {
        id: "details",
        title: "Thông tin chi tiết",
        paragraphs: [
          `Sản phẩm ${seed.name} chính hãng từ ${seed.brand}.`,
          `Sản phẩm được ${(seed.warranty ?? "bảo hành chính hãng").toLowerCase()}.`,
        ],
      },
      {
        id: "notes",
        title: "Lưu ý khi sử dụng",
        paragraphs: [
          "Kiểm tra sản phẩm và phụ kiện đi kèm khi nhận hàng.",
          "Lắp đặt và sử dụng sản phẩm theo đúng hướng dẫn của nhà sản xuất.",
        ],
      },
    ];

  return {
    ...seed,
    slug: seed.id,
    sku: seed.id.toUpperCase().replaceAll("-", "_"),
    shortDescription: seed.highlights.join(" • "),
    description,
    image: placeholderImage,
    images: [placeholderImage],
    discount,
    status: seed.stockQuantity === 0 ? "out-of-stock" : seed.status ?? "in-stock",
    warranty: seed.warranty ?? "Bảo hành chính hãng 24 tháng",
    rating: 4.8,
    reviewCount: 12,
    featuredSpecs,
    bundles: seed.bundles ?? [],
    contentSections,
    specificationGroups: [
      {
        title: "Thông số nổi bật",
        items: featuredSpecs,
      },
    ],
  };
}

